SELECT COUNT(*)
  FROM users
 WHERE 1=1

   AND tenant_id = #{tenantId}


   AND org_id = #{orgId}

SELECT user_id AS userId, username, name, role_key AS roleKey, org_id AS orgId, enabled FROM users WHERE 1=1
AND tenant_id = #{tenantId}
AND org_id = #{orgId}
ORDER BY user_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.sql:

AND u.tenant_id = #{tenantId}


AND u.org_id = #{orgId}


AND (u.name ILIKE '%' || #{keyword} || '%'
  OR u.username ILIKE '%' || #{keyword} || '%')

AND u.enabled = TRUE
